package com.booksyde.service; import com.booksyde.exception.BusinessException; import java.net.*; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.util.regex.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; @Service public class GoogleDriveService {private final String key;private final HttpClient http=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NORMAL).build();public GoogleDriveService(@Value("${booksyde.google.drive-api-key:}")String k){key=k;} public String folderId(String s){var m=Pattern.compile("/folders/([a-zA-Z0-9_-]+)").matcher(s==null?"":s.trim());if(m.find())return m.group(1);return s!=null&&s.matches("^[a-zA-Z0-9_-]{10,}$")?s:null;} public String list(String folder){if(key.isBlank())throw new BusinessException("Google Drive API não configurada.");try{String q=URLEncoder.encode("'"+folder+"' in parents and trashed = false",StandardCharsets.UTF_8);var u=URI.create("https://www.googleapis.com/drive/v3/files?q="+q+"&fields=files(id,name,mimeType,size)&pageSize=1000&orderBy=name_natural&key="+URLEncoder.encode(key,StandardCharsets.UTF_8));var r=http.send(HttpRequest.newBuilder(u).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new BusinessException("Google Drive recusou a listagem.");return r.body();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new BusinessException("Consulta ao Drive interrompida.");}catch(Exception e){if(e instanceof BusinessException b)throw b;throw new BusinessException("Falha ao consultar Google Drive.");}} public HttpResponse<byte[]> file(String id){try{var u=URI.create("https://www.googleapis.com/drive/v3/files/"+URLEncoder.encode(id,StandardCharsets.UTF_8)+"?alt=media&key="+URLEncoder.encode(key,StandardCharsets.UTF_8));return http.send(HttpRequest.newBuilder(u).GET().build(),HttpResponse.BodyHandlers.ofByteArray());}catch(Exception e){throw new BusinessException("Falha ao baixar arquivo do Drive.");}}}